-- GenDB engine variant Q15-conjunct_permutation: template q15.sql, kind conjunct_permutation (generated by generate.py; frozen)
WITH revenue0 AS (
  SELECT
    l_suppkey AS supplier_no,
    SUM(l_extendedprice * (
      1 - l_discount
    )) AS total_revenue
  FROM lineitem
  WHERE
    l_shipdate < $1 + INTERVAL '3 MONTH' AND l_shipdate >= $1
  GROUP BY
    l_suppkey
)
SELECT
  s_suppkey,
  s_name,
  s_address,
  s_phone,
  total_revenue
FROM supplier, revenue0
WHERE
  total_revenue = (
    SELECT
      MAX(total_revenue)
    FROM revenue0
  )
  AND s_suppkey = supplier_no
ORDER BY
  s_suppkey
